CREATE TRIGGER ZT_ZPERSON_ZFACECOUNT_ZDETECTEDFACE_ZPERSONFORFACE_UPDATE_DECREMENT AFTER UPDATE OF ZPERSONFORFACE ON ZDETECTEDFACE WHEN (OLD.ZHIDDEN == 0 AND OLD.ZASSETVISIBLE == 1 AND OLD.ZCENTERX != 0) AND ((OLD.ZPERSONFORFACE IS NOT NULL AND NEW.ZPERSONFORFACE IS NULL) OR (NEW.ZPERSONFORFACE != OLD.ZPERSONFORFACE)) BEGIN UPDATE ZPERSON SET ZFACECOUNT = MAX(0,IFNULL(ZFACECOUNT,0) - 1) WHERE Z_PK = OLD.ZPERSONFORFACE; SELECT NSCoreDataTriggerUpdateAffectedObjectValue('ZPERSON', Z_ENT, Z_PK, 'ZFACECOUNT', ZFACECOUNT) FROM ZPERSON WHERE Z_PK = OLD.ZPERSONFORFACE; END;
